using LGSTrayPrimitives;
using Microsoft.Win32;
using System;
using System.Collections.Generic;
using System.Globalization;
using System.Linq;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
using System.Windows.Threading;
namespace LGSTrayUI;
internal sealed partial class RingSettingsWindow
{
    private FrameworkElement ThemePreview(RingPreferences theme){var strip=new StackPanel{Orientation=Orientation.Horizontal,HorizontalAlignment=HorizontalAlignment.Center};foreach(var (type,level) in new[]{(DeviceType.Mouse,85),(DeviceType.Headset,65),(DeviceType.Keyboard,15),(DeviceType.Gamepad,8)})strip.Children.Add(new BatteryRing{Width=45,Height=45,Margin=new Thickness(2),Preferences=theme,PreviewLight=false,DataContext=new TaskbarBattery(type,type.ToString(),level,"已连接",false,DateTimeOffset.MinValue,devices.FirstOrDefault(d=>d.Type==type)?.Key??("theme:"+type))});return new Border{Background=BrushFor("#20242C"),CornerRadius=new CornerRadius(7),Child=new Viewbox{Stretch=Stretch.Uniform,StretchDirection=StretchDirection.DownOnly,HorizontalAlignment=HorizontalAlignment.Center,Child=strip},Padding=new Thickness(8)};}
    private FrameworkElement ThemeCard(string name,RingPreferences theme,bool custom){var card=new StackPanel();card.Children.Add(ThemePreview(theme));card.Children.Add(new TextBlock{Text=name,FontSize=16,FontWeight=FontWeights.SemiBold,TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,10,0,3)});var colors=new Grid{Margin=new Thickness(0,5,0,9)};var swatches=new[]{theme.Normal,theme.Low,theme.Critical,theme.Offline};for(int i=0;i<swatches.Length;i++){colors.ColumnDefinitions.Add(new ColumnDefinition());var swatch=new Border{Background=BrushFor(swatches[i]),Height=18,CornerRadius=new CornerRadius(5),Margin=new Thickness(0,0,i==3?0:6,0),ToolTip=new[]{"正常电量","低电量","极低电量","离线"}[i]+" · "+swatches[i]};Grid.SetColumn(swatch,i);colors.Children.Add(swatch);}card.Children.Add(colors);var footer=new DockPanel{LastChildFill=true};var apply=Btn("应用",()=>{RingThemes.Apply(theme);RingConfig.Notify();Build();});apply.Margin=new Thickness(8,3,0,3);apply.MinWidth=64;DockPanel.SetDock(apply,Dock.Right);footer.Children.Add(apply);var buttons=new WrapPanel();if(custom){buttons.Children.Add(Btn("重命名",()=>RenameTheme(name,theme)));buttons.Children.Add(Btn("导出",()=>{var f=new SaveFileDialog{Filter="JSON|*.json",FileName="battery-theme.json"};if(f.ShowDialog()==true)System.IO.File.WriteAllText(f.FileName,System.Text.Json.JsonSerializer.Serialize(theme));}));buttons.Children.Add(Btn("删除",()=>{if(MessageBox.Show("删除主题 "+name+"？","主题",MessageBoxButton.YesNo)==MessageBoxResult.Yes){RingThemes.Delete(name);Build();}}));}footer.Children.Add(buttons);card.Children.Add(footer);var box=PanelCard(card,14);box.Margin=new Thickness(0);box.HorizontalAlignment=HorizontalAlignment.Stretch;return box;}
    private void ThemeCards(Panel parent){TitleLine(parent,"预设主题");var grid=new ThemeTilePanel{Margin=new Thickness(0,0,0,18)};foreach(var t in PresetThemes())grid.Children.Add(ThemeCard(t.Name,t.Settings,false));parent.Children.Add(grid);}

    private void AppearanceThemeSelector(Panel p){var row=new DockPanel{Margin=new Thickness(0,0,0,8)};var lab=Label("主题  ");DockPanel.SetDock(lab,Dock.Left);row.Children.Add(lab);var built=PresetThemes();var names=built.Select(t=>t.Name).Concat(RingThemes.All.Keys).Prepend("当前自定义设置").ToArray();var selector=new ComboBox{ItemsSource=names,SelectedIndex=0};row.Children.Add(selector);selector.SelectionChanged+=(_,_)=>{int i=selector.SelectedIndex;if(i<=0)return;if(i<=built.Length)RingThemes.Apply(built[i-1].Settings);else if(RingThemes.All.TryGetValue(names[i],out var t))RingThemes.Apply(t);RingConfig.Notify();Build();};p.Children.Add(row);}
    private static (string Name,RingPreferences Settings)[] PresetThemes()=>new[]{("Apple Classic",new RingPreferences()),("Ocean Blue",new RingPreferences{Normal="#0A84FF",Low="#64D2FF",Critical="#BF5AF2"}),("Pastel Pink",new RingPreferences{Normal="#F5A9CF",Low="#C8B6FF",Critical="#FF7799"}),("Minimal White",new RingPreferences{Normal="#FFFFFF",Low="#BBBBBB",Critical="#888888"})};

    private void SaveThemeDialog(){var input=new TextBox{MinWidth=260,Margin=new Thickness(0,8,0,8)};var panel=new StackPanel{Margin=new Thickness(20)};panel.Children.Add(Label("输入主题名称（保存外观、布局、动画和设备配色）"));panel.Children.Add(input);var w=new Window{Title="保存主题",Owner=this,SizeToContent=SizeToContent.WidthAndHeight,WindowStartupLocation=WindowStartupLocation.CenterOwner,Content=panel,Background=Background,Foreground=Foreground,ResizeMode=ResizeMode.NoResize};panel.Children.Add(Btn("保存",()=>{var name=input.Text.Trim();if(name.Length==0)return;if(RingThemes.All.ContainsKey(name)&&MessageBox.Show(w,"覆盖同名主题？","主题",MessageBoxButton.YesNo)!=MessageBoxResult.Yes)return;try{RingThemes.Save(name,C);w.Close();if(nav.SelectedIndex==6)Build();}catch(Exception ex){MessageBox.Show(w,ex.Message);}}));w.ShowDialog();}
    private void SavedThemeCards(Panel parent){TitleLine(parent,"我的主题");var grid=new ThemeTilePanel{Margin=new Thickness(0,0,0,10)};foreach(var item in RingThemes.All.ToArray())grid.Children.Add(ThemeCard(item.Key,item.Value,true));if(grid.Children.Count>0)parent.Children.Add(grid);else parent.Children.Add(PanelCard(new TextBlock{Text="尚无自定义主题。保存当前设置即可创建。",TextWrapping=TextWrapping.Wrap,Opacity=.75,Margin=new Thickness(0,8,0,8)}));var actions=new WrapPanel();actions.Children.Add(Btn("导入主题…",()=>{var f=new OpenFileDialog{Filter="JSON|*.json"};if(f.ShowDialog()==true)try{var t=System.Text.Json.JsonSerializer.Deserialize<RingPreferences>(System.IO.File.ReadAllText(f.FileName))??throw new FormatException();RingThemes.Save(System.IO.Path.GetFileNameWithoutExtension(f.FileName),t);Build();}catch(Exception ex){MessageBox.Show(ex.Message);}}));parent.Children.Add(actions);}
    private void RenameTheme(string old,RingPreferences theme){var input=new TextBox{Text=old,MinWidth=260,Margin=new Thickness(0,8,0,8)};var panel=new StackPanel{Margin=new Thickness(20)};panel.Children.Add(Label("新主题名称"));panel.Children.Add(input);var w=new Window{Title="重命名主题",Owner=this,SizeToContent=SizeToContent.WidthAndHeight,WindowStartupLocation=WindowStartupLocation.CenterOwner,Content=panel,Background=Background,Foreground=Foreground,ResizeMode=ResizeMode.NoResize};panel.Children.Add(Btn("保存",()=>{var name=input.Text.Trim();if(name.Length==0||name==old){w.Close();return;}if(RingThemes.All.ContainsKey(name)){MessageBox.Show(w,"主题名称已存在。");return;}try{RingThemes.Save(name,theme);RingThemes.Delete(old);w.Close();Build();}catch(Exception ex){MessageBox.Show(w,ex.Message);}}));w.ShowDialog();}
}
